\label{Aut(H/E)}
Let $E\subseteq H$, $U\in \ensuremath{\text{Aut}}(H,\pi)$. Then $U\in \ensuremath{\text{Aut}}((H,\pi)/E)$ if and only if:
\begin{itemize}
\item For all $v\in H$ and all $a\in\mathcal{A}$, $U(\pi(a)(v))=\pi(a)(Uv)$.
\item For all $w\in H_E$, $Uw=w$.
\end{itemize}

\label{independenceoverempty}\label{independenceoverA}\label{RemarkItIsEnoughIndependenceForOneVector}
Let $\bar v$, $\bar w\in H^n$ and $E\subseteq H$. Then it is easy to see that:
\begin{itemize}
\item $\bar v$ is independent from $\bar w$ over $\emptyset$ if and only if for every $j,k=1,\dots,n$, $H_{(v_j)_e}\perp H_{(w_k)_e}$.
\item $\bar v$ is independent from $\bar w$ over $E$ if and only if for every $j,k=1,\dots,n$, $H_{P_E^\perp(v_j)_e}\perp H_{P_E^\perp(w_k)_e}$.
\item $\bar v\in H^n$ and $E$, $F\subseteq H$. Then $\bar v\ind^*_EF$ if and only if for every $j=1,\dots,n$ $v_j\ind^*_EF$ that is, for all $j=1,\dots,n$ $P_{acl(E)}(v_j)=P_{acl(E\cup F)}(v_j)$.
\end{itemize}

\label{nonforkingextension}
Let $E\subseteq F\subseteq H$, $p\in S_n(E)$ $q\in S_n(F)$ and $\bar v=(v_1,\dots,v_n)$, $\bar w=(v_1,\dots,v_n)\in H^n$ be such that $p=tp(\bar v/E)$ and $q=tp(\bar w/F)$. Then $q$ is an extension of $p$ such that $\bar w\ind^*_EF$ if and only if the following conditions hold:
    \begin{enumerate}
        \item For every $j=1,\dots,n$, $P_{acl(E)}(v_j)=P_{acl(F)}(w_j)$
        \item For every $j=1,\dots,n$, $(H_{P^\perp_{acl(E)}v_j},\pi_{P^\perp_{acl(E)}v_j},P^\perp_{acl(E)}v_j)$ is isometrically isomorphic to $(H_{P^\perp_{acl(F)}w_j},\pi_{P^\perp_{acl(F)}w_j},P^\perp_{acl(F)}w_j)$
    \end{enumerate}

\label{relationsbetweenpositivelinearfunctionals}
Let $\phi$ and $\psi$ be positive linear functionals on $\mathcal{A}$.
\begin{enumerate}
\item They are called \textit{orthogonal} ($\phi\perp\psi$) if $\|\phi-\psi\|=\|\phi\|+\|\psi\|$.
\item Also, $\phi$ is called \textit{dominated} by $\psi$ ($\phi\leq\psi$) if there exist $\gamma>0$ such that the functional $\gamma\psi-\phi$ is positive.

\end{enumerate}

\label{orthogonalityoverempty}
Let $p,q\in S_1(\emptyset)$, let $v$, $w\in H$ be such that $v\models p$ and $w\models q$.
Then, $p\perp^a q$ if and only if $\phi_{v_e}\perp \phi_{w_e}$.

\label{orthogonalityoverA}
Let $E\subseteq H$. Let $p,q\in
S_1(E)$, let $v$, $w\in H$ be such that $v\models p$ and $w\models q$. Then, $p\perp_E^a q$ if and only if $\phi_{P^\perp_E(v_e)}\perp \phi_{P^\perp_E(w_e)}$

\label{dominationoverempty}
Let $p,q\in S_1(\emptyset)$ and let $v$, $w\in H$ be such that $v\models p$ and $w\models q$.
Then, $p\vartriangleright_\emptyset q$ if and only if $\phi_{w_e}\leq\phi_{v_e}$.
